#pragma once

#include "engine/modules/animation/IAnimation.hpp"

namespace RType {

    /**
     * @brief Loops over a horizontal strip of frames in a sprite sheet.
     *
     * Frame i is the rectangle {i * width, top, width, height}: sheets are
     * generated by tools/generate_assets.py with frames packed edge to edge.
     */
    class AAnimation : public IAnimation {
    public:
        AAnimation(float top, float width, float height, int frameCount, float frameDuration)
                : _top(top), _width(width), _height(height), _frameCount(frameCount),
                  _frameDuration(frameDuration) {}

        RectFloat update() override {
            _frameIndex = (_frameIndex + 1) % _frameCount;
            return getCurrentFrame();
        }

        [[nodiscard]] RectFloat getCurrentFrame() const override {
            return {static_cast<float>(_frameIndex) * _width, _top, _width, _height};
        }

        [[nodiscard]] float getFrameDuration() const override { return _frameDuration; }

    private:
        float _top;
        float _width;
        float _height;
        int _frameCount;
        float _frameDuration;
        int _frameIndex = 0;
    };
}
